import{z as A,x as s,o as E,c as d,q as l,j as t,D as e,d as r,s as n,S as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"正则线性模型","description":"","frontmatter":{"title":"正则线性模型","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/regularized-linear-alpha.md","filePath":"quant/regularized-linear-alpha.md","lastUpdated":1791063341000}'),o={name:"quant/regularized-linear-alpha.md"};function p(m,a,h,_,u,b){const i=s("Mermaid");return E(),d("div",null,[a[2]||(a[2]=l('<h1 id="正则线性模型" tabindex="-1">正则线性模型 <a class="header-anchor" href="#正则线性模型" aria-label="Permalink to &quot;正则线性模型&quot;">​</a></h1><div class="epigraph"><p>收缩方法在最小二乘与空模型之间连续插值；惩罚不是装饰，而是在高维里让线性预测有定义的那一项。</p><footer>—— 据 Hastie, Tibshirani and Friedman, The Elements of Statistical Learning 对岭回归与套索的论述整理</footer></div><p><a href="/quant/gbdt-alpha">上一课</a>把 GBDT 写成表格截面的标准非线性基线：正则与早停是必需品，时间切分、purge 与按列滞后比树的深度更决定是否泄漏。缺口是线性层还没有作为公平对照写清。特征一多，普通最小二乘把噪声方向当成信号；Gu–Kelly–Xiu 把惩罚线性当作机器学习的基准层，而不是被树取代的过时物。本课写岭回归、套索与弹性网如何改变可识别的 \\(w\\)。不重讲叶子分裂。后课未来函数默认已经读完：验证集如何避免把未来写进特征是下一课，本课假定 \\(X_t\\) 在 \\(t\\) 日可获得。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>设 \\(t\\) 日截面有 \\(N_t\\) 只股票、\\(p\\) 个特征。无惩罚的目标是</p> \\[\\min_w\\ \\frac1{N_t}\\|r_{t+1}-X_t w\\|_2^2. \\]<p>\\(p\\) 相对 \\(N_t\\) 并不小：行业哑元、交互、滞后已经把 \\(p\\) 顶到几十上百；再叠非线性基，普通最小二乘的设计矩阵病态。相关特征（账面市值与盈利、动量与反转）让 \\(X^\\top X\\) 的小特征值把系数炸开，样本内 \\(R^2\\) 好看，样本外 IC 崩溃。这不是优化器脾气坏，而是<a href="/quant/cov-shrinkage">误差最大化</a>在预测侧的翻版：未正则的 \\(\\hat w\\) 偏爱估得最不准的方向。</p><p>资产定价还多一条约束：你要的不是拟合历史收益，而是可交易的下一期排序。系数不稳定会直接变成换手。Hastie、Tibshirani 与 Friedman 把偏差–方差写成显式权衡：惩罚增大，有效自由度下降，方差下降，偏差上升。问题是选哪一种范数、惩罚相对哪一个尺度，以及验证集如何避免把未来写进特征——后者交给<a href="/quant/no-future-function">防止未来函数</a>，本篇假定 \\(X_t\\) 在 \\(t\\) 日收盘后可获得。</p><h3 id="最小二乘在截面上的两种病" tabindex="-1">最小二乘在截面上的两种病 <a class="header-anchor" href="#最小二乘在截面上的两种病" aria-label="Permalink to &quot;最小二乘在截面上的两种病&quot;">​</a></h3><p>第一种病是共线：价值与质量、规模与流动性高度相关，OLS 会把符号拆成「一个巨大正、一个巨大负」，经济上无法读。第二种病是稀疏错觉的反面：真正起作用的特征可能只有一小撮，但 OLS 把系数均匀洒在所有列上，噪声列分到的权重在下一期变号。套索针对第二种，岭回归针对第一种；弹性网承认两者同时存在。Gu–Kelly–Xiu 的线性基准表明，在特征已经标准化、并做行业或市值中性之后，惩罚线性往往已经吃掉树模型相对 OLS 的大部分增益——增益来自正则，不一定来自深度。</p><p><span class="marginnote">系数爆炸的数字版：两个特征相关 0.99 时，标准化设计矩阵的最小特征值约为 \\(1-\\rho = 0.01\\)，求逆放大 100 倍——于是系数变成「一个 +8.3、一个 −7.9」，单独看哪个都无法解释。岭回归把特征值从 0.01 抬到 \\(0.01+\\lambda\\)，取 \\(\\lambda=1\\) 时放大倍数掉回约 1 倍，符号立刻能读：这就是「\\(\\lambda\\) 让逆不再爆炸」的具体样子。</span></p><p><span class="marginnote">惩罚的对象是系数，不是预测本身。把收益 winsorize、把特征横截面标准化，是另一层稳健；它们改变的是 \\(X\\) 与 \\(r\\) 的尺度，不能替代 \\(\\|w\\|\\) 上的约束。混在一个网格里调，最后说不清是谁在干活。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>岭回归在残差平方和上加 \\(\\lambda\\|w\\|_2^2\\)，解为 \\((X^\\top X+\\lambda I)^{-1}X^\\top r\\)。\\(\\lambda\\) 把特征值从 \\(\\xi_j\\) 抬到 \\(\\xi_j+\\lambda\\)，逆不再爆炸。套索把惩罚换成 \\(\\lambda\\|w\\|_1\\)，在 \\(p\\) 大时把一部分系数精确打到零，相当于连续的子集选择。弹性网是 \\(\\lambda\\bigl(\\alpha\\|w\\|_1+(1-\\alpha)\\|w\\|_2^2/2\\bigr)\\)：\\(\\ell_1\\) 做选择，\\(\\ell_2\\) 在高度相关的一组特征之间分摊，避免套索在共线簇里任意挑一个。Zou 与 Hastie（2005）证明，纯套索在 \\(p\\gt n\\) 时最多选出 \\(n\\) 个变量，且对相关变量不稳定；弹性网修的就是这两条。</p><p>估计应在时间上滚动，而不是全样本一次。每个再训练日 \\(t\\)，只用 \\(t\\) 之前的 \\((X_s,r_{s+1})\\)，用净化后的验证窗选 \\(\\lambda\\)（见 purged k-fold）。特征必须先做横截面标准化或分位变换，否则惩罚会按原始量纲偏爱低方差列。行业、市值中性可以放进 \\(X\\) 的残差化，也可以放进组合构造；不要两头都做却只报告一次。评价用下一期截面 IC、分位多空与<a href="/quant/net-edge">扣费后净期望</a>，不要用样本内 \\(R^2\\)。</p><p><span class="marginnote">为什么惩罚前必须标准化：\\(\\|w\\|\\) 对系数量纲敏感。假设「市值」按亿元计、「动量」按小数计，量纲大的特征系数天然小、被罚得轻，惩罚等于暗中偏爱某些列。横截面标准化把每列方差拉到 1 之后，同一个 \\(\\lambda\\) 才对所有特征一视同仁——这一步不做，调 \\(\\lambda\\) 调的是量纲，不是复杂度。</span></p><h3 id="惩罚与组合排序不是同一实验" tabindex="-1">惩罚与组合排序不是同一实验 <a class="header-anchor" href="#惩罚与组合排序不是同一实验" aria-label="Permalink to &quot;惩罚与组合排序不是同一实验&quot;">​</a></h3><p>线性模型给出每只股票一个分数，随后仍要<a href="/quant/long-short-sort">排序形成多空</a>。惩罚改变的是分数的平滑程度，不自动给出断点、加权与持有期。把套索选出的十个特征再拿去等权打分，等于丢掉了它估出来的相对幅度；把岭回归的分数直接按市值加权持有，则换手由分数的自相关决定，与 \\(\\lambda\\) 耦合。正确的报告是：固定排序规则，只让 \\(\\lambda\\) 变，画出 IC、换手、净夏普对 \\(\\lambda\\) 的路径。Hastie 等人强调用交叉验证选惩罚；金融里验证窗必须尊重时间与事件依赖，否则「最优 \\(\\lambda\\)」本身是过拟合。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>岭回归的机制是收缩：每个主成分方向上的系数被乘以 \\(\\xi_j/(\\xi_j+\\lambda)\\)。大特征值（共同因子）几乎不缩，小特征值（噪声）被按死。于是预测靠近低维因子结构，这与基本面风险模型把收益写成 \\(Bf+\\varepsilon\\) 是同一几何，只是这里收缩的是预测系数而不是协方差。套索的机制是软阈值：在正交设计下，系数按绝对值减去 \\(\\lambda\\) 再截断。相关设计下没有这么干净的图，但直觉仍是「付一笔固定的 \\(\\ell_1\\) 税，不够大的系数活不下来」。弹性网让同一簇里的特征一起进、一起出，适合「账面、盈利、现金流其实是同一价值簇」这种资产定价现实。</p><p><span class="marginnote">收缩可以类比调音台：数据里的每个主成分方向是一路音轨，OLS 把每路推子都推到样本内最响的位置——噪声轨也被推满。岭回归把所有推子统一往下拉，大信号（共同因子）拉得少、噪声轨几乎拉没；套索干脆把不够响的轨静音（系数精确为零）；弹性网让同一簇音轨一起进一起出。\\(\\lambda\\) 就是总音量旋钮。</span></p>',21)),(E(),t(B,null,{default:e(()=>[n(i,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E5%90%8C%E4%B8%80%E7%9B%B8%E5%85%B3%E7%89%B9%E5%BE%81%E7%B0%87%3A%20%E4%BB%B7%E5%80%BC%E4%B8%89%E5%85%84%E5%BC%9F%22%5D%20--%3E%20RIDGE%5B%22%E5%B2%AD%3A%20%E5%85%A8%E4%BF%9D%E7%95%99%2C%20%E4%B8%80%E8%B5%B7%E7%BC%A9%E5%B0%8F%20%CE%BE%2F(%CE%BE%2B%CE%BB)%22%5D%0A%20%20B%20--%3E%20LASSO%5B%22%E5%A5%97%E7%B4%A2%3A%20%E8%BD%AF%E9%98%88%E5%80%BC%2C%20%E7%95%99%E4%B8%80%E4%B8%AA%E5%85%B6%E4%BD%99%E6%89%93%E9%9B%B6%22%5D%0A%20%20B%20--%3E%20EN%5B%22%E5%BC%B9%E6%80%A7%E7%BD%91%3A%20%E4%B8%80%E8%B5%B7%E8%BF%9B%E4%B8%80%E8%B5%B7%E5%87%BA%2C%20%E7%BB%84%E5%86%85%E5%88%86%E6%91%8A%22%5D%0A%20%20RIDGE%20--%3E%20ST%5B%22%E7%B3%BB%E6%95%B0%E7%A8%B3%E5%AE%9A%2C%20%E6%96%B9%E5%B7%AE%E4%B8%8B%E9%99%8D%22%5D%0A%20%20LASSO%20--%3E%20SP%5B%22%E6%A8%A1%E5%9E%8B%E7%A8%80%E7%96%8F%2C%20%E5%8F%AF%E8%A7%A3%E9%87%8A%22%5D%0A%20%20EN%20--%3E%20BOTH%5B%22%E6%97%A2%E7%A8%80%E7%96%8F%E5%8F%88%E7%A8%B3%E5%AE%9A%22%5D%0A%20%20ST%20--%3E%20TR%5B%22%CE%BB%20%E8%B6%8A%E5%A4%A7%3A%20%E5%81%8F%E5%B7%AE%E8%B6%8A%E5%A4%A7%2C%20%E6%8D%A2%E6%89%8B%E8%B6%8A%E4%BD%8E%22%5D%0A%20%20SP%20--%3E%20TR%0A%20%20BOTH%20--%3E%20TR%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l('<p>可交易性上，收缩降低换手，因为 \\(\\hat w_t\\) 对样本扰动不那么跳。这是正则相对无惩罚 OLS 最被低估的好处：夏普的改善常常来自成本，而不是来自更高的毛 IC。过强的 \\(\\ell_1\\) 会把慢变量（价值）留下、把快变量（短期反转）删掉，策略在制度上更像低换手风险溢价；过弱则回到噪声换手。\\(\\lambda\\) 因此既是统计量，也是换手旋钮。</p><p><span class="marginnote">不要把套索的零系数读成「该特征无定价能力」。它只是在当前惩罚、当前相关结构下没进模型。换一个样本年、换一种中性化，同一特征可以复活。稳定的说法是系数路径，不是某一 \\(\\lambda\\) 上的活跃集。</span></p><h3 id="点-in-time-面板上的额外偏倚" tabindex="-1">点-in-time 面板上的额外偏倚 <a class="header-anchor" href="#点-in-time-面板上的额外偏倚" aria-label="Permalink to &quot;点-in-time 面板上的额外偏倚&quot;">​</a></h3><p>A 股的因变量常被涨跌停截断：真实意愿收益不可观测，OLS 与惩罚回归都把截断当真实 \\(r\\)。这会把「封板后的动量」写成可线性拟合的 alpha，其实是不可成交的价格。停牌、新股、ST 进出样本造成非随机缺失。正则不修复缺失机制；它只是让你在脏数据上得到一个更平滑的错误。正确顺序是：先按交易所规则构造可成交收益与可获得特征，再谈 \\(\\lambda\\)。把市值、行业做成特征而不做中性，惩罚可能把规模当成最强的一列——那是<a href="/quant/size-neutral">规模暴露</a>，不是新 alpha。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>正则线性假定近似线性可加。阈值效应、状态依赖、拥挤非线性，套索不会帮你发现，只会把它们摊成偏差。树模型与神经网络可以表达这些，但把自由度交回去；没有惩罚与净化验证，复杂度只是把过拟合从系数挪到结构。Gu–Kelly–Xiu 的比较有用，恰恰因为他们给了惩罚线性一个公平的位置：它是必须先打败的基准，不是故事的反派。</p><p>超参不要在全样本上用夏普去选。\\(\\lambda\\) 选得让样本内多空最漂亮，等于把验证集变成训练集。也不要把岭回归的 \\(\\lambda\\) 与 Ledoit–Wolf 的 \\(\\delta\\) 混成一个「收缩系数」：前者惩罚预测权重，后者收缩协方差，进入组合的方式不同。实务上的稳健栈往往是：点-in-time 特征、横截面标准化、弹性网或岭、滚动再训练、再用组合层的权重约束做第二层正则。两层都要，一层不够。</p><p><span class="marginnote">标准化必须用 \\(t\\) 日可获得的截面均值与方差，或用过去窗口。用含 \\(t+1\\) 的全样本均值去中心化，是最廉价的未来函数。惩罚再漂亮，也救不了输入里的泄漏。</span></p>',8)),(E(),t(B,null,{default:e(()=>[n(i,{id:"mermaid-84",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E7%82%B9-in-time%20%E7%89%B9%E5%BE%81%20X_t%22%5D%20--%3E%20Z%5B%22%E6%A8%AA%E6%88%AA%E9%9D%A2%E6%A0%87%E5%87%86%E5%8C%96%20%2F%20%E4%B8%AD%E6%80%A7%E5%8C%96%22%5D%0A%20%20Z%20--%3E%20PEN%5B%22%E5%B2%AD%20%2F%20%E5%A5%97%E7%B4%A2%20%2F%20%E5%BC%B9%E6%80%A7%E7%BD%91%22%5D%0A%20%20Y%5B%22%E4%B8%8B%E4%B8%80%E6%9C%9F%E5%8F%AF%E6%88%90%E4%BA%A4%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20PEN%0A%20%20PEN%20--%3E%20W%5B%22%E6%94%B6%E7%BC%A9%E5%90%8E%E7%9A%84%E6%96%9C%E7%8E%87%20w%22%5D%0A%20%20W%20--%3E%20S%5B%22%E6%88%AA%E9%9D%A2%E5%88%86%E6%95%B0%20alpha%22%5D%0A%20%20S%20--%3E%20SORT%5B%22%E6%8E%92%E5%BA%8F%E4%B8%8E%E5%A4%9A%E7%A9%BA%22%5D%0A%20%20SORT%20--%3E%20COST%5B%22%E6%8D%A2%E6%89%8B%E4%B8%8E%E5%87%80%E6%9C%9F%E6%9C%9B%22%5D%0A%20%20PEN%20--%3E%20CV%5B%22%E6%97%B6%E9%97%B4%E5%87%80%E5%8C%96%E4%BA%A4%E5%8F%89%E9%AA%8C%E8%AF%81%E9%80%89%20%CE%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=l('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>高维线性 alpha 的失败首先是未惩罚的病态设计矩阵，不是「线性太简单」。</li><li>岭回归收缩共线方向，套索做连续子集选择，弹性网在相关簇上同时选择与分摊；出处见 Hoerl–Kennard（1970）、Tibshirani（1996）、Zou–Hastie（2005）与 ESL。</li><li>惩罚降低有效自由度，往往同时降低换手；\\(\\lambda\\) 是统计旋钮也是成本旋钮。</li><li>评价必须用可成交的下一期收益与样本外 IC，而不是样本内 \\(R^2\\)。</li><li>截断收益、非随机缺失与特征泄漏不属于正则能修的层。</li><li>惩罚线性是机器学习定价的基准层，见 Gu, Kelly and Xiu, <em>Review of Financial Studies</em>, 2020。</li><li>出处：Hastie, Tibshirani, Friedman, <em>The Elements of Statistical Learning</em>；Tibshirani, <em>JRSS-B</em>, 1996；Zou and Hastie, <em>JRSS-B</em>, 2005。</li></ul>',2))])}const D=A(o,[["render",p]]);export{c as __pageData,D as default};
